from collections import deque

def bfs_at_depth(graph, start, target_depth):
    # BFS to find nodes at exactly target_depth
    visited = {start}
    current_depth = 0
    current_level = {start}

    while current_depth < target_depth:
        next_level = set()
        for node in current_level:
            for neighbor in graph.get(node, []):
                if neighbor not in visited:
                    next_level.add(neighbor)
                    visited.add(neighbor)
        current_level = next_level
        current_depth += 1
        print(f"Depth {current_depth}: {len(current_level)} nodes")
        if len(current_level) == 0:
            break

    return sorted(list(current_level))

result = bfs_at_depth(graph, 'b3e3e393c7', 8)
